// Template della dashboard "Allineamento sales Digiduu" (allineamento_sales_template.html),
// incorporato tale e quale: il segnaposto __DATA__ viene sostituito con il
// documento JSON della generazione (vedi page.tsx). Rigenerare questo file dal
// template HTML invece di modificarlo a mano.
export const ALLINEAMENTO_SALES_TEMPLATE = "<!DOCTYPE html>\n<html lang=\"it\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Allineamento sales Digiduu</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:opsz,wght@12..96,500;12..96,700;12..96,800&family=Figtree:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n<style>\n:root{\n  --ink:#1D1A33; --ink2:#55516B; --ink3:#8C88A3;\n  --paper:#F6F5F9; --card:#FFFFFF; --line:#E4E1EE;\n  --violet:#5A3FD0; --violet2:#9C88F0; --lilac:#ECE7FF;\n  --amber:#C97A0E; --amberBg:#FFF3DF;\n  --green:#1F7A52; --greenBg:#E2F4EA;\n  --red:#B53F28; --redBg:#FBE7E2;\n  --disp:\"Bricolage Grotesque\", \"Segoe UI\", system-ui, sans-serif;\n  --body:\"Figtree\", \"Segoe UI\", system-ui, sans-serif;\n}\n*{box-sizing:border-box}\nhtml,body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--body);font-size:15px;line-height:1.45}\nbutton,select,input{font:inherit;color:inherit}\n:focus-visible{outline:2px solid var(--violet);outline-offset:2px}\n.wrap{max-width:1360px;margin:0 auto;padding:20px 28px 60px}\n\n/* barra superiore */\n.top{display:flex;flex-wrap:wrap;align-items:flex-end;justify-content:space-between;gap:16px;padding-bottom:14px;border-bottom:1px solid var(--line)}\n.brand{font-family:var(--disp);font-weight:800;font-size:22px;letter-spacing:-.01em}\n.brand small{display:block;font-family:var(--body);font-weight:500;font-size:13px;color:var(--ink3);letter-spacing:0}\n.controls{display:flex;flex-wrap:wrap;gap:10px;align-items:center}\n.controls label{font-size:13px;color:var(--ink2);display:flex;gap:6px;align-items:center}\n.controls select,.controls input[type=date]{border:1px solid var(--line);background:var(--card);border-radius:8px;padding:6px 10px}\n\n/* schede vista */\n.tabs{display:flex;gap:4px;margin:22px 0 6px;flex-wrap:wrap}\n.tab{border:0;background:none;cursor:pointer;padding:6px 14px 8px 0;margin-right:18px;font-family:var(--disp);font-weight:700;font-size:28px;letter-spacing:-.02em;color:var(--ink3);border-bottom:3px solid transparent}\n.tab:hover{color:var(--ink2)}\n.tab[aria-selected=true]{color:var(--ink);border-bottom-color:var(--violet)}\n.lede{color:var(--ink2);margin:6px 0 22px;max-width:75ch}\n\n/* indicatore budget */\n.gauge{background:var(--ink);color:#fff;border-radius:16px;padding:22px 26px 20px;margin-bottom:22px}\n.gauge-head{display:flex;flex-wrap:wrap;justify-content:space-between;align-items:baseline;gap:12px}\n.gauge-num{font-family:var(--disp);font-weight:800;font-size:46px;letter-spacing:-.03em;line-height:1}\n.gauge-num span{font-size:20px;font-weight:500;color:#B9B3D6;letter-spacing:0;margin-left:6px}\n.gauge-side{text-align:right;font-size:14px;color:#D6D1EE}\n.gauge-side b{font-family:var(--disp);font-size:24px;color:#fff;display:block}\n.bar{position:relative;height:30px;margin:22px 0 10px;background:#34304F;border-radius:6px;overflow:visible;display:flex}\n.seg{height:100%;cursor:pointer;transition:filter .15s}\n.seg:hover{filter:brightness(1.15)}\n.seg:first-child{border-radius:6px 0 0 6px}\n.seg.won{background:#3CC48A}\n.seg.prop{background:var(--violet2)}\n.seg.prev{background:#C9BEF5}\n.seg.fatt{background:#3CC48A}.seg.bozza{background:#6FA8F5}.seg.off{background:var(--violet2)}.seg.cons{background:#F2C14E}.seg.poss{background:repeating-linear-gradient(135deg,#C9BEF5 0 6px,#C9BEF588 6px 12px)}\n.gauge-sub{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;margin-top:16px;padding-top:14px;border-top:1px solid #3A3558}\n.gauge-sub button{background:none;border:0;color:#D6D1EE;text-align:left;cursor:pointer;padding:0;font-size:13px}\n.gauge-sub button b{display:block;font-family:var(--disp);font-size:20px;color:#fff}\n.gauge-sub button:hover b{text-decoration:underline}\n.gauge-sub i{display:inline-block;width:10px;height:10px;border-radius:3px;margin-right:6px}\n.year{display:grid;grid-template-columns:repeat(12,1fr);gap:6px;align-items:end;height:190px;padding-top:20px;position:relative}\n.year .col{display:flex;flex-direction:column;justify-content:flex-end;height:100%;cursor:pointer;position:relative}\n.year .col .b{border-radius:4px 4px 0 0;width:100%}\n.year .col span{font-size:11px;line-height:16px;height:16px;color:var(--ink3);text-align:center;margin-top:4px}\n.year .col em{font-style:normal;font-size:11px;color:var(--ink2);text-align:center;font-variant-numeric:tabular-nums}\n.year .col.cur span{color:var(--ink);font-weight:700}\n.year .line{position:absolute;left:0;right:0;border-top:2px dashed var(--red);opacity:.55;pointer-events:none}\n.year .line::after{content:'Budget 200 k€';position:absolute;right:0;top:-18px;font-size:11px;color:var(--red);font-weight:600}\n.target{position:absolute;top:-8px;bottom:-8px;width:2px;background:#fff}\n.target::after{content:attr(data-l);position:absolute;top:-20px;left:50%;transform:translateX(-50%);font-size:12px;white-space:nowrap;color:#fff;font-weight:600}\n.legend{display:flex;flex-wrap:wrap;gap:6px 20px;font-size:13px;color:#D6D1EE}\n.legend i{display:inline-block;width:11px;height:11px;border-radius:3px;margin-right:6px;vertical-align:-1px}\n.legend button{background:none;border:0;color:inherit;cursor:pointer;padding:0;text-align:left}\n.legend button:hover{color:#fff;text-decoration:underline}\n.toggle{display:flex;align-items:center;gap:8px;margin-top:12px;font-size:13px;color:#D6D1EE}\n\n/* riquadri numerici */\n.kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:12px;margin-bottom:24px}\n.kpi{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:14px 16px;text-align:left;cursor:pointer}\n.kpi:hover{border-color:var(--violet2)}\n.kpi .n{font-family:var(--disp);font-weight:700;font-size:30px;letter-spacing:-.02em;line-height:1.1}\n.kpi .l{font-size:13px;color:var(--ink2)}\n.kpi .s{font-size:13px;color:var(--ink3);margin-top:2px}\n.kpi.warn{background:var(--amberBg);border-color:#F1D3A0}\n.kpi.warn .n{color:var(--amber)}\n.kpi.good .n{color:var(--green)}\n.kpi.bad .n{color:var(--red)}\n\n/* sezioni */\n.grid2{display:grid;grid-template-columns:1fr 1fr;gap:22px}\n.grid2>div{min-width:0}\n@media (max-width:980px){.grid2{grid-template-columns:1fr}}\nsection.block{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:18px 18px 8px;margin-bottom:22px;min-width:0}\n.block h3{font-family:var(--disp);font-weight:700;font-size:19px;margin:0 0 2px;letter-spacing:-.01em;display:flex;gap:10px;align-items:baseline;flex-wrap:wrap}\n.block h3 .cnt{font-family:var(--body);font-size:13px;font-weight:600;color:var(--ink3)}\n.block .hint{font-size:13px;color:var(--ink2);margin:0 0 10px}\n.empty{padding:14px 0 16px;color:var(--ink2);font-size:14px}\n.callout{background:var(--amberBg);border:1px solid #F1D3A0;border-radius:12px;padding:12px 16px;margin-bottom:22px;font-size:14px;display:flex;gap:12px;align-items:flex-start}\n.callout b{color:var(--amber)}\n\n/* tabelle */\n.tw{overflow-x:auto;margin:0 -18px;padding:0 18px}\ntable{border-collapse:collapse;width:100%;font-size:14px}\nth{font-size:12px;font-weight:600;color:var(--ink3);text-align:left;padding:6px 10px 6px 0;border-bottom:1px solid var(--line);white-space:nowrap}\ntd{padding:9px 10px 9px 0;border-bottom:1px solid #F0EEF5;vertical-align:top}\ntr.row{cursor:pointer}\ntr.row:hover td{background:#FAF9FD}\ntd.num,th.num{text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap}\ntd.opp{font-weight:600;min-width:200px}\ntd.opp small{display:block;font-weight:400;color:var(--ink3)}\n.zero{color:var(--amber);font-weight:600}\n.chip{display:inline-block;font-size:12px;padding:2px 8px;border-radius:999px;background:#F1EFF7;color:var(--ink2);white-space:nowrap;margin:0 4px 3px 0}\n.chip.st-Proposta{background:var(--lilac);color:var(--violet)}\n.chip.st-Fare{background:#F4F0FF;color:#6E58D6}\n.chip.st-Vinta{background:var(--greenBg);color:var(--green)}\n.chip.lost{background:var(--redBg);color:var(--red)}\n.chip.nodate{background:var(--amberBg);color:var(--amber)}\n.stars{color:#E3A008;letter-spacing:1px;white-space:nowrap}\n.stars .off{color:#DCD8E8}\n.act{font-size:13px;color:var(--ink2);min-width:180px}\n.act .d{font-weight:600;color:var(--ink)}\n.act .d.late{color:var(--red)}\n\n/* elenco eventi */\n.feed{list-style:none;margin:0;padding:0}\n.feed li{display:grid;grid-template-columns:76px 1fr auto;gap:12px;padding:10px 0;border-bottom:1px solid #F0EEF5;cursor:pointer;align-items:start}\n.feed li:hover{background:#FAF9FD}\n.feed .when{font-size:13px;color:var(--ink3);font-variant-numeric:tabular-nums}\n.feed .what b{font-weight:600}\n.feed .what .sub{font-size:13px;color:var(--ink2)}\n.feed .amt{font-variant-numeric:tabular-nums;font-weight:600;white-space:nowrap}\n.tag-ev{font-size:11px;font-weight:700;padding:2px 7px;border-radius:5px;margin-right:6px;vertical-align:1px}\n.ev-new{background:#E7F0FF;color:#2B5DB8}.ev-stage{background:var(--lilac);color:var(--violet)}\n.ev-rev{background:var(--amberBg);color:var(--amber)}.ev-won{background:var(--greenBg);color:var(--green)}\n.ev-lost{background:var(--redBg);color:var(--red)}.ev-user{background:#F1EFF7;color:var(--ink2)}\n\n/* finestra di dettaglio */\ndialog{border:0;border-radius:18px;padding:0;max-width:760px;width:calc(100% - 32px);max-height:88vh;box-shadow:0 30px 80px #1D1A3355;color:var(--ink)}\ndialog::backdrop{background:#1D1A3399}\n.dlg-head{padding:22px 26px 14px;border-bottom:1px solid var(--line);position:sticky;top:0;background:#fff;z-index:1}\n.dlg-head h2{font-family:var(--disp);font-size:24px;margin:0 40px 4px 0;letter-spacing:-.02em;line-height:1.15}\n.dlg-head .p{color:var(--ink2)}\n.close{position:absolute;right:16px;top:16px;border:0;background:#F1EFF7;width:34px;height:34px;border-radius:50%;cursor:pointer;font-size:18px}\n.dlg-body{padding:18px 26px 24px}\n.facts{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px 18px;margin-bottom:18px}\n.facts div{font-size:13px;color:var(--ink3)}\n.facts b{display:block;font-size:15px;color:var(--ink);font-weight:600}\n.dlg-body h4{font-family:var(--disp);font-size:16px;margin:18px 0 6px}\n.list-plain{list-style:none;margin:0;padding:0}\n.list-plain li{padding:8px 0;border-bottom:1px solid #F0EEF5;font-size:14px}\n.list-plain li .m{font-size:12px;color:var(--ink3)}\n.btn{display:inline-block;background:var(--violet);color:#fff;text-decoration:none;padding:9px 16px;border-radius:10px;font-weight:600;font-size:14px;margin-top:16px}\n.foot{font-size:12px;color:var(--ink3);margin-top:30px}\n@media (prefers-reduced-motion:reduce){*{transition:none!important}}\n@media (max-width:640px){.wrap{padding:14px}.tab{font-size:21px;margin-right:8px}.gauge-num{font-size:34px}.feed li{grid-template-columns:60px 1fr}.feed .amt{grid-column:2}}\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n  <header class=\"top\">\n    <div class=\"brand\">Allineamento sales Digiduu<small id=\"srcNote\"></small></div>\n    <div class=\"controls\">\n      <label>Mese <select id=\"monthSel\"></select></label>\n      <label>Data di riferimento <input type=\"date\" id=\"refDate\"></label>\n      <label>Addetto vendite <select id=\"userSel\"><option value=\"\">Tutti</option></select></label>\n    </div>\n  </header>\n\n  <nav class=\"tabs\" role=\"tablist\">\n    <button class=\"tab\" role=\"tab\" data-v=\"week\">Settimana</button>\n    <button class=\"tab\" role=\"tab\" data-v=\"start\">Inizio mese</button>\n    <button class=\"tab\" role=\"tab\" data-v=\"mid\">Metà mese</button>\n    <button class=\"tab\" role=\"tab\" data-v=\"end\">Fine mese</button>\n    <button class=\"tab\" role=\"tab\" data-v=\"year\">Anno</button>\n  </nav>\n  <main id=\"view\"></main>\n  <p class=\"foot\">Dati CRM Odoo, solo Digiduu S.r.l.: opportunità aperte, vinte da luglio, perse da settembre, attività aperte e storico modifiche da ottobre. Il fatturato previsto del mese viene dalla pipeline commerciale: fatture Digiduu confermate e in bozza più piano di fatturazione in Proposta e Consuntivi (le righe Target sono mostrate a parte e non sommate). Fasi e valori delle opportunità aperte sono quelli alla data di estrazione, anche se scegli una data di riferimento precedente. Clicca su qualsiasi riga, numero o barra per vedere il dettaglio.</p>\n</div>\n\n<dialog id=\"dlg\"><div id=\"dlgIn\"></div></dialog>\n\n<script>\nconst DATA = __DATA__;\nconst BUDGET = DATA.budget;\nconst STAGES_CLOSE = ['Proposta','Fare preventivo'];\nconst byId = new Map(DATA.leads.map(l=>[l.id,l]));\nconst actsBy = {}; DATA.activities.forEach(a=>{(actsBy[a.lead] ||= []).push(a)});\nObject.values(actsBy).forEach(v=>v.sort((a,b)=>a.date.localeCompare(b.date)));\nconst trackBy = {}; DATA.tracking.forEach(t=>{(trackBy[t.lead] ||= []).push(t)});\n\nconst st = { view:'start', ref:DATA.extracted, user:'', undated:false };\nconst TODAY = () => st.ref < DATA.extracted ? st.ref : DATA.extracted;\n\n/* utilità */\nconst eur = v => v==null ? '' : new Intl.NumberFormat('it-IT',{style:'currency',currency:'EUR',maximumFractionDigits:0,useGrouping:'always'}).format(v);\nconst eurK = v => v>=1000 ? (Math.round(v/100)/10).toLocaleString('it-IT')+' k€' : eur(v);\nconst MESI = ['gennaio','febbraio','marzo','aprile','maggio','giugno','luglio','agosto','settembre','ottobre','novembre','dicembre'];\nconst d = s => new Date(s+'T00:00:00');\nconst iso = dt => dt.getFullYear()+'-'+String(dt.getMonth()+1).padStart(2,'0')+'-'+String(dt.getDate()).padStart(2,'0');\nconst addDays = (s,n)=>{const x=d(s);x.setDate(x.getDate()+n);return iso(x)};\nconst fd = s => { if(!s) return ''; const x=d(s); return x.getDate()+' '+MESI[x.getMonth()].slice(0,3)+(x.getFullYear()!==d(st.ref).getFullYear()?' '+x.getFullYear():''); };\nconst monthStart = s => s.slice(0,8)+'01';\nconst monthEnd = s => { const x=d(s); return iso(new Date(x.getFullYear(),x.getMonth()+1,0)); };\nconst monthName = s => MESI[d(s).getMonth()];\nconst inR = (s,a,b) => s && s>=a && s<=b;\nconst esc = s => String(s??'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]));\nconst uOk = l => !st.user || l.user===st.user;\nconst daysBetween=(a,b)=>Math.round((d(b)-d(a))/864e5);\n\nconst openLeads = () => DATA.leads.filter(l=>l.status==='open' && uOk(l));\nconst nextAct = l => (actsBy[l.id]||[])[0];\nconst stars = p => '<span class=\"stars\" aria-label=\"Priorità '+p+' su 3\">'+[1,2,3].map(i=>i<=p?'★':'<span class=\"off\">★</span>').join('')+'</span>';\nconst stageChip = s => '<span class=\"chip '+(s==='Proposta'?'st-Proposta':s==='Fare preventivo'?'st-Fare':s==='Vinta'?'st-Vinta':(s==='Chiusa persa'?'lost':''))+'\">'+esc(s)+'</span>';\n\n/* pipeline commerciale (fatture + piano di fatturazione) */\nconst PSTATES=[['Fatturato','fatt','#3CC48A','Fatture confermate'],['Contrattualizzato','bozza','#6FA8F5','Fatture in bozza'],['Consuntivi','cons','#F2C14E','Piano di fatturazione a consuntivo'],['Offerta probabile','off','#9C88F0','Piano in Proposta, fattibilità probabile'],['Offerta possibile','poss','#C9BEF5','Piano in Proposta, fattibilità possibile']];\nconst pOk=r=>!st.user||r.account===st.user;\nfunction pipeMonth(m){\n  const rows=DATA.pipeline.filter(r=>r.month===m&&pOk(r));\n  const by={}; PSTATES.forEach(([s])=>by[s]=rows.filter(r=>r.state===s));\n  const v=s=>by[s].reduce((a,r)=>a+r.value,0);\n  const target=rows.filter(r=>r.state==='Target');\n  const forecast=PSTATES.reduce((a,[s])=>a+v(s),0);\n  const detail=m>=DATA.pipeDetailFrom;\n  return {m,rows,by,v,target,forecast:detail?forecast:(st.user?null:(DATA.pipeMonthly[m]||0)),detail};\n}\nfunction pipeGauge(title){\n  const p=pipeMonth(st.ref.slice(0,7));\n  const tot=p.forecast||0, scale=Math.max(BUDGET*1.15,tot), w=v=>(v/scale*100)+'%';\n  const gap=BUDGET-tot;\n  setPipeLists(p);\n  return '<div class=\"gauge\"><div class=\"gauge-head\"><div><div style=\"font-size:14px;color:#B9B3D6;margin-bottom:6px\">'+title+'</div><div class=\"gauge-num\">'+eur(tot)+'<span>su '+eur(BUDGET)+'</span></div><div style=\"font-size:14px;color:#D6D1EE;margin-top:8px\">Senza le offerte possibili: <b style=\"color:#fff\">'+eur(tot-p.v('Offerta possibile'))+'</b></div></div>'\n   +'<div class=\"gauge-side\">'+(gap>0?'Mancano<b>'+eur(gap)+'</b>':'Sopra budget<b>+'+eur(-gap)+'</b>')+'</div></div>'\n   +'<div class=\"bar\">'+PSTATES.map(([s,c])=>'<div class=\"seg '+c+'\" style=\"width:'+w(p.v(s))+'\" data-p=\"'+s+'\" title=\"'+s+' '+eur(p.v(s))+'\"></div>').join('')\n   +'<div class=\"target\" style=\"left:'+w(BUDGET)+'\" data-l=\"Budget '+eurK(BUDGET)+'\"></div></div>'\n   +'<div class=\"gauge-sub\">'+PSTATES.map(([s,c,col,h])=>'<button data-p=\"'+s+'\"><i style=\"background:'+col+'\"></i>'+s+'<b>'+eur(p.v(s))+'</b>'+h+' · '+p.by[s].length+' righe</button>').join('')\n   +(p.target.length?'<button data-p=\"Target\"><i style=\"background:#fff\"></i>Target (non sommato)<b>'+eur(p.target.reduce((a,r)=>a+r.value,0))+'</b>Righe Target del piano</button>':'')+'</div>'\n   +'<div style=\"font-size:12px;color:#8F89AE;margin-top:12px\">Fonte: pipeline commerciale Odoo (fatture Digiduu + piano di fatturazione)'+(st.user?', filtrata per account del cliente':'')+'.</div></div>';\n}\nlet PIPE_LISTS={};\nfunction setPipeLists(p){PIPE_LISTS={};PSTATES.forEach(([s])=>PIPE_LISTS[s]=p.by[s]);PIPE_LISTS.Target=p.target;PIPE_LISTS.__all=p.rows.filter(r=>r.state!=='Target')}\nfunction pipeTable(rows){\n  if(!rows.length) return '<div class=\"empty\">Nessuna riga.</div>';\n  rows=[...rows].sort((a,b)=>b.value-a.value);\n  return '<div class=\"tw\"><table><thead><tr><th>Cliente</th><th>Ordine</th><th>Descrizione</th><th>Stato</th><th>Fattibilità</th><th>Account</th><th class=\"num\">Importo</th></tr></thead><tbody>'\n   +rows.map(r=>'<tr><td style=\"font-weight:600\">'+esc(r.partner)+'</td><td>'+esc(r.order)+'</td><td>'+esc(r.desc)+'</td><td><span class=\"chip\">'+esc(r.state)+'</span></td><td>'+esc(r.fatt||'–')+'</td><td>'+esc(r.account)+'</td><td class=\"num\">'+eur(r.value)+'</td></tr>').join('')\n   +'</tbody></table></div>';\n}\nfunction openPipe(key){\n  const rows=PIPE_LISTS[key]||[]; const tot=rows.reduce((a,r)=>a+r.value,0);\n  dlgIn.innerHTML='<div class=\"dlg-head\"><button class=\"close\" aria-label=\"Chiudi\">×</button><h2>'+(key==='__all'?'Fatturato previsto':esc(key))+' di '+monthName(st.ref)+'</h2><div class=\"p\">'+rows.length+' righe · '+eur(tot)+'</div></div><div class=\"dlg-body\">'+pipeTable(rows)+'</div>';\n  dlg.showModal();\n}\nfunction pipeByAccount(){\n  const p=pipeMonth(st.ref.slice(0,7)); if(!p.detail) return '<div class=\"empty\">Dettaglio per account disponibile da settembre.</div>';\n  const accs=[...new Set(p.rows.map(r=>r.account))].sort((a,b)=>a==='Non assegnato'?1:b==='Non assegnato'?-1:a.localeCompare(b));\n  if(!accs.length) return '<div class=\"empty\">Nessuna riga in pipeline per il mese.</div>';\n  const tot=accs.map(a=>{const r=p.rows.filter(x=>x.account===a);const s=k=>r.filter(x=>x.state===k).reduce((q,x)=>q+x.value,0);return [a,...PSTATES.map(([k])=>s(k)),PSTATES.reduce((q,[k])=>q+s(k),0)]});\n  return '<div class=\"tw\"><table><thead><tr><th>Account</th>'+PSTATES.map(([s])=>'<th class=\"num\">'+s+'</th>').join('')+'<th class=\"num\">Totale</th></tr></thead><tbody>'\n   +tot.map(r=>'<tr class=\"row\" data-acc=\"'+esc(r[0])+'\"><td style=\"font-weight:600\">'+esc(r[0])+'</td>'+r.slice(1).map((v,i)=>'<td class=\"num\"'+(i===r.length-2?' style=\"font-weight:700\"':'')+'>'+(v?eur(v):'–')+'</td>').join('')+'</tr>').join('')\n   +'</tbody></table></div>';\n}\nfunction yearChart(){\n  const y=st.ref.slice(0,4); const cur=st.ref.slice(0,7);\n  const vals=[...Array(12)].map((_,i)=>{const m=y+'-'+String(i+1).padStart(2,'0');return [m,pipeMonth(m).forecast]});\n  const max=Math.max(BUDGET*1.15,...vals.map(v=>v[1]||0));\n  return '<div class=\"year\"><div class=\"line\" style=\"bottom:'+(20+BUDGET/max*150)+'px\"></div>'\n   +vals.map(([m,v],i)=>'<div class=\"col'+(m===cur?' cur':'')+'\" title=\"'+MESI[i]+': '+(v==null?'n.d.':eur(v))+'\"><em>'+(v==null?'n.d.':eurK(v))+'</em><div class=\"b\" style=\"height:'+((v||0)/max*150)+'px;background:'+(m<cur?'#3CC48A':m===cur?'var(--violet)':'#C9BEF5')+'\"></div><span>'+MESI[i].slice(0,3)+'</span></div>').join('')+'</div>';\n}\n\n/* collegamento opportunità -> previsione fatture */\nconst hasPlan = l => !!(DATA.planCovered||{})[l.id];\nconst ordersOf = l => (DATA.leadOrders||{})[l.id]||[];\nconst ordersTxt = l => { const o=ordersOf(l).filter(x=>x[1]!=='annullato'); return o.length? o.map(x=>x[0]+' ('+x[1]+')').join(', ') : ''; };\nfunction noPlanList(){ return openLeads().filter(l=>STAGES_CLOSE.includes(l.stage)&&!hasPlan(l)).sort((a,b)=>(a.stage===b.stage?0:a.stage==='Proposta'?-1:1)||b.rev-a.rev); }\nfunction noPlanBlock(){\n  const list=noPlanList(), tot=list.reduce((s,l)=>s+l.rev,0);\n  const unl=(DATA.planUnlinked||[]).filter(r=>!st.user||(DATA.pipeline.find(p=>p.order===r.order)||{}).account===st.user);\n  return block('Proposte e preventivi senza previsione fatture',list.length+' · '+eur(tot),'Opportunità in Proposta e Fare preventivo il cui preventivo non ha righe del piano di fatturazione in Proposta: non entrano nel fatturato previsto finché non si pianificano le tranche.',\n    table(list,{orders:true,empty:'Tutte le proposte hanno una previsione fatture collegata.'})\n    +(unl.length?'<p class=\"hint\" style=\"margin-top:12px\">Righe del piano in Proposta su preventivi non collegati ad alcuna opportunità: '+unl.map(r=>esc(r.partner)+' '+r.order+' ('+eur(r.value)+')').join(', ')+'. Probabilmente vanno collegate all’opportunità corretta.</p>':''));\n}\n\n/* calcolo del mese */\nfunction monthCalc(){\n  const ms=monthStart(st.ref), me=monthEnd(st.ref);\n  const won = DATA.leads.filter(l=>l.status==='won' && uOk(l) && inR(l.closed,ms,me));\n  const lost = DATA.leads.filter(l=>l.status==='lost' && uOk(l) && inR(l.closed,ms,me));\n  const pipe = openLeads().filter(l=>STAGES_CLOSE.includes(l.stage));\n  const dated = pipe.filter(l=>inR(l.deadline,ms,me));\n  const prop = dated.filter(l=>l.stage==='Proposta'), prev = dated.filter(l=>l.stage==='Fare preventivo');\n  const undated = pipe.filter(l=>!l.deadline);\n  const late = pipe.filter(l=>l.deadline && l.deadline<TODAY());\n  const sum = a=>a.reduce((s,l)=>s+l.rev,0);\n  return {ms,me,won,lost,pipe,prop,prev,undated,late,sum,\n    wonV:sum(won),propV:sum(prop),prevV:sum(prev),undV:sum(undated)};\n}\n\n/* eventi nel periodo */\nfunction events(a,b){\n  const ev=[];\n  DATA.leads.forEach(l=>{\n    if(!uOk(l)) return;\n    if(inR(l.created,a,b)) ev.push({date:l.created,type:'new',lead:l,label:'Nuova',txt:'Creata · oggi in '+l.stage,amt:l.rev});\n    if(l.status==='won' && inR(l.closed,a,b)) ev.push({date:l.closed,type:'won',lead:l,label:'Vinta',txt:'Chiusa vinta',amt:l.rev});\n    if(l.status==='lost' && inR(l.closed,a,b)) ev.push({date:l.closed,type:'lost',lead:l,label:'Persa',txt:'Motivo: '+(l.lostReason||'non indicato')+' · era in '+l.stage,amt:l.rev});\n  });\n  DATA.tracking.forEach(t=>{\n    const l=byId.get(t.lead); if(!l||!uOk(l)||!inR(t.date,a,b)) return;\n    if(t.kind==='S'){ if(t.new==='Vinta'||t.new==='Chiusa persa') return;\n      ev.push({date:t.date,type:'stage',lead:l,label:'Fase',txt:t.old+' → '+t.new+' (da '+t.author+')',amt:null,to:t.new}); }\n    if(t.kind==='R') ev.push({date:t.date,type:'rev',lead:l,label:'Valore',txt:eur(t.old)+' → '+eur(t.new)+' (da '+t.author+')',amt:t.new-t.old,delta:true});\n    if(t.kind==='U') ev.push({date:t.date,type:'user',lead:l,label:'Addetto',txt:t.old+' → '+t.new,amt:null});\n  });\n  return ev.sort((x,y)=>y.date.localeCompare(x.date));\n}\n\n/* componenti */\nfunction table(list,opts={}){\n  if(!list.length) return '<div class=\"empty\">'+(opts.empty||'Niente da mostrare.')+'</div>';\n  const cols = opts.closed\n    ? ['Opportunità','Addetto','Fase','Chiusa il','Etichette e motivo','Revenue']\n    : ['Opportunità','Addetto','Fase','Chiusura','Etichette','Revenue','Priorità',...(opts.orders?['Preventivo Odoo']:[]),'Prossima attività'];\n  let h='<div class=\"tw\"><table><thead><tr>'+cols.map(c=>'<th'+(c==='Revenue'?' class=\"num\"':'')+'>'+c+'</th>').join('')+'</tr></thead><tbody>';\n  list.forEach(l=>{\n    const na=nextAct(l);\n    h+='<tr class=\"row\" tabindex=\"0\" data-id=\"'+l.id+'\"><td class=\"opp\">'+esc(l.name)+'<small>'+esc(l.partner)+'</small></td><td>'+esc(l.user)+'</td><td>'+stageChip(l.stage)+'</td>';\n    if(opts.closed){\n      h+='<td>'+fd(l.closed)+'</td><td>'+(l.tags||[]).map(t=>'<span class=\"chip\">'+esc(t)+'</span>').join('')+(l.lostReason?'<span class=\"chip lost\">'+esc(l.lostReason)+'</span>':'')+'</td><td class=\"num\">'+eur(l.rev)+'</td>';\n    } else {\n      h+='<td>'+(l.deadline?fd(l.deadline):'<span class=\"chip nodate\">da inserire</span>')+'</td>'\n        +'<td>'+(l.tags.length?l.tags.map(t=>'<span class=\"chip\">'+esc(t)+'</span>').join(''):'<span style=\"color:var(--ink3)\">–</span>')+'</td>'\n        +'<td class=\"num\">'+(l.rev>0?eur(l.rev):'<span class=\"zero\">da valorizzare</span>')+'</td>'\n        +'<td>'+stars(l.prio)+'</td>'\n        +(opts.orders?'<td style=\"white-space:nowrap;font-size:13px\">'+(ordersTxt(l)||'<span class=\"zero\">nessun preventivo</span>')+'</td>':'')\n        +'<td class=\"act\">'+(na?'<span class=\"d'+(na.date<TODAY()?' late':'')+'\">'+fd(na.date)+'</span> '+esc(na.type)+(na.summary?': '+esc(na.summary):'')+'<br><span style=\"color:var(--ink3)\">'+esc(na.user)+'</span>':'<span class=\"zero\">nessuna attività</span>')+'</td>';\n    }\n    h+='</tr>';\n  });\n  return h+'</tbody></table></div>';\n}\nfunction block(title,count,hint,body){\n  return '<section class=\"block\"><h3>'+title+(count!=null?' <span class=\"cnt\">'+count+'</span>':'')+'</h3>'+(hint?'<p class=\"hint\">'+hint+'</p>':'')+body+'</section>';\n}\nconst kpi=(n,l,s,cls,key)=>'<button class=\"kpi '+(cls||'')+'\" data-k=\"'+key+'\"><div class=\"n\">'+n+'</div><div class=\"l\">'+l+'</div>'+(s?'<div class=\"s\">'+s+'</div>':'')+'</button>';\nfunction feed(ev){\n  if(!ev.length) return '<div class=\"empty\">Nessun movimento registrato nel periodo.</div>';\n  return '<ul class=\"feed\">'+ev.map(e=>'<li tabindex=\"0\" data-id=\"'+e.lead.id+'\"><span class=\"when\">'+fd(e.date)+'</span><span class=\"what\"><span class=\"tag-ev ev-'+e.type+'\">'+e.label+'</span><b>'+esc(e.lead.name)+'</b><div class=\"sub\">'+esc(e.txt)+' · '+esc(e.lead.user)+'</div></span><span class=\"amt\">'+(e.amt?(e.delta&&e.amt>0?'+':'')+eur(e.amt):'')+'</span></li>').join('')+'</ul>';\n}\nfunction gauge(c,title,showUndatedToggle){\n  const total = c.wonV+c.propV+c.prevV;\n  const extra = st.undated? c.undV:0;\n  const scale = Math.max(BUDGET*1.15, total+extra);\n  const w=v=>(v/scale*100)+'%';\n  const gap = Math.max(0,BUDGET-total-extra);\n  return '<div class=\"gauge\"><div class=\"gauge-head\"><div><div style=\"font-size:14px;color:#B9B3D6;margin-bottom:6px\">'+title+'</div><div class=\"gauge-num\">'+eur(total+extra)+'<span>su '+eur(BUDGET)+'</span></div></div>'\n   +'<div class=\"gauge-side\">'+(gap>0?'Mancano<b>'+eur(gap)+'</b>':'Budget raggiunto<b>+'+eur(total+extra-BUDGET)+'</b>')+'</div></div>'\n   +'<div class=\"bar\">'\n     +'<div class=\"seg won\" style=\"width:'+w(c.wonV)+'\" data-k=\"won\" title=\"Vinto '+eur(c.wonV)+'\"></div>'\n     +'<div class=\"seg prop\" style=\"width:'+w(c.propV)+'\" data-k=\"prop\" title=\"Proposta '+eur(c.propV)+'\"></div>'\n     +'<div class=\"seg prev\" style=\"width:'+w(c.prevV)+'\" data-k=\"prev\" title=\"Fare preventivo '+eur(c.prevV)+'\"></div>'\n     +(st.undated?'<div class=\"seg undated\" style=\"width:'+w(c.undV)+'\" data-k=\"undated\" title=\"Senza data '+eur(c.undV)+'\"></div>':'')\n     +'<div class=\"target\" style=\"left:'+w(BUDGET)+'\" data-l=\"Budget '+eurK(BUDGET)+'\"></div></div>'\n   +'<div class=\"legend\">'\n     +'<button data-k=\"won\"><i style=\"background:#3CC48A\"></i>Vinto nel mese '+eur(c.wonV)+' ('+c.won.length+')</button>'\n     +'<button data-k=\"prop\"><i style=\"background:var(--violet2)\"></i>Proposta in chiusura '+eur(c.propV)+' ('+c.prop.length+')</button>'\n     +'<button data-k=\"prev\"><i style=\"background:#C9BEF5\"></i>Fare preventivo in chiusura '+eur(c.prevV)+' ('+c.prev.length+')</button>'\n     +(st.undated?'<button data-k=\"undated\"><i style=\"background:#F2B451\"></i>Senza data di chiusura '+eur(c.undV)+' ('+c.undated.length+')</button>':'')\n   +'</div>'\n   +(showUndatedToggle?'<label class=\"toggle\"><input type=\"checkbox\" id=\"undTgl\" '+(st.undated?'checked':'')+'> Aggiungi le opportunità in Proposta e Fare preventivo senza data di chiusura ('+eur(c.undV)+')</label>':'')\n   +'</div>';\n}\nfunction undatedCallout(c){\n  if(!c.undated.length) return '';\n  return '<div class=\"callout\"><div><b>'+c.undated.length+' opportunità in Proposta o Fare preventivo non hanno la chiusura prevista</b> (valore '+eur(c.undV)+'). Senza data non si capisce quali possono chiudersi a '+monthName(st.ref)+' e colmare il gap. <a href=\"#\" data-k=\"undated\" style=\"color:var(--amber);font-weight:600\">Vedi elenco</a></div></div>';\n}\nfunction byUserTable(rowsFn,cols){\n  const users=[...new Set(DATA.leads.filter(l=>l.status==='open'||true).map(l=>l.user))].filter(u=>!st.user||u===st.user).sort();\n  const data=users.map(u=>[u,...rowsFn(u)]).filter(r=>r.slice(1).some(v=>v&&v!=='0'&&v!==0&&v!=='–'));\n  if(!data.length) return '<div class=\"empty\">Nessun dato.</div>';\n  return '<div class=\"tw\"><table><thead><tr><th>Addetto</th>'+cols.map(c=>'<th class=\"num\">'+c+'</th>').join('')+'</tr></thead><tbody>'\n   +data.map(r=>'<tr class=\"row\" data-user=\"'+esc(r[0])+'\"><td style=\"font-weight:600\">'+esc(r[0])+'</td>'+r.slice(1).map(v=>'<td class=\"num\">'+v+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';\n}\n\n/* liste richiamabili dai numeri */\nlet LISTS={};\nfunction setLists(o){LISTS=o}\n\n/* viste */\nfunction vWeek(){\n  const a=addDays(st.ref,-6), b=st.ref;\n  const ev=events(a,b);\n  const g=t=>ev.filter(e=>e.type===t);\n  const wonV=g('won').reduce((s,e)=>s+e.lead.rev,0), lostV=g('lost').reduce((s,e)=>s+e.lead.rev,0);\n  const revD=g('rev').reduce((s,e)=>s+e.amt,0);\n  const openIds=new Set(openLeads().map(l=>l.id));\n  const actsOpen=DATA.activities.filter(x=>openIds.has(x.lead));\n  const next7=actsOpen.filter(x=>x.date>st.ref && x.date<=addDays(st.ref,7)).sort((x,y)=>x.date.localeCompare(y.date));\n  const today=actsOpen.filter(x=>x.date===st.ref);\n  const overdue=actsOpen.filter(x=>x.date<TODAY()).sort((x,y)=>y.date.localeCompare(x.date));\n  setLists({\n    new:['Nuove opportunità della settimana',g('new').map(e=>e.lead)],\n    stage:['Cambi di fase della settimana',[...new Set(g('stage').map(e=>e.lead))]],\n    rev:['Valorizzazioni della settimana',[...new Set(g('rev').map(e=>e.lead))]],\n    won:['Vinte nella settimana',g('won').map(e=>e.lead),true],\n    lost:['Perse nella settimana',g('lost').map(e=>e.lead),true],\n    overdue:['Opportunità con attività scadute',[...new Set(overdue.map(x=>byId.get(x.lead)))]]\n  });\n  const actList=(list,empty)=>!list.length?'<div class=\"empty\">'+empty+'</div>':'<ul class=\"feed\">'+list.map(x=>{const l=byId.get(x.lead);return '<li tabindex=\"0\" data-id=\"'+l.id+'\"><span class=\"when\">'+fd(x.date)+'</span><span class=\"what\"><b>'+esc(l.name)+'</b><div class=\"sub\">'+esc(x.type)+(x.summary?': '+esc(x.summary):'')+'</div></span><span class=\"amt\" style=\"font-weight:500;color:var(--ink2)\">'+esc(x.user)+'</span></li>'}).join('')+'</ul>';\n  return '<p class=\"lede\">Allineamento interno: cosa si è mosso nel CRM dal '+fd(a)+' al '+fd(b)+' e cosa c’è in agenda nei prossimi 7 giorni.</p>'\n   +'<div class=\"kpis\">'\n     +kpi(g('new').length,'Nuove opportunità','',' ','new')\n     +kpi(g('stage').length,'Cambi di fase','','','stage')\n     +kpi(g('rev').length,'Valorizzazioni',(revD>=0?'+':'')+eur(revD),'','rev')\n     +kpi(eur(wonV),'Vinte',g('won').length+' opportunità','good','won')\n     +kpi(eur(lostV),'Perse',g('lost').length+' opportunità','bad','lost')\n     +kpi(overdue.length,'Attività scadute','su opportunità aperte',overdue.length?'warn':'','overdue')\n   +'</div>'\n   +'<div class=\"grid2\"><div>'+block('Novità della settimana',ev.length,'Creazioni, cambi di fase, valori, riassegnazioni, vinte e perse.',feed(ev))+'</div>'\n   +'<div>'+block('In agenda oggi e nei prossimi 7 giorni',today.length+next7.length,'Attività aperte sulle opportunità in corso.',actList([...today,...next7],'Nessuna attività pianificata: è il momento di fissare i prossimi passi.'))\n   +block('Attività scadute',overdue.length,'Da chiudere o ripianificare in Odoo.',actList(overdue.slice(0,25),'Nessuna attività scaduta.')+(overdue.length>25?'<div class=\"empty\">… e altre '+(overdue.length-25)+'. <a href=\"#\" data-k=\"overdue\">Vedi tutte</a></div>':''))+'</div></div>';\n}\n\nfunction vStart(){\n  const c=monthCalc();\n  const zero=c.pipe.filter(l=>!l.rev);\n  const sortRev=a=>[...a].sort((x,y)=>y.prio-x.prio||y.rev-x.rev);\n  const propUnd=sortRev(c.undated.filter(l=>l.stage==='Proposta'&&l.rev>0)), prevUnd=sortRev(c.undated.filter(l=>l.stage==='Fare preventivo'&&l.rev>0));\n  setLists({won:['Vinte nel mese',c.won,true],prop:['Proposta con chiusura nel mese',c.prop],prev:['Fare preventivo con chiusura nel mese',c.prev],undated:['Proposta e Fare preventivo senza data di chiusura',sortRev(c.undated)],zero:['Da valorizzare',zero],late:['Chiusura prevista già passata',c.late],noplan:['Senza previsione fatture',noPlanList(),false,true]});\n  return '<p class=\"lede\">Piano di '+monthName(st.ref)+': il fatturato previsto dalla pipeline commerciale contro il budget di '+eur(BUDGET)+', e le opportunità CRM in Proposta e Fare preventivo da chiudere per colmare la differenza.</p>'\n   +pipeGauge('Fatturato previsto di '+monthName(st.ref))\n   +undatedCallout(c)\n   +'<div class=\"kpis\">'\n     +kpi(c.prop.length,'Proposte in chiusura',eur(c.propV),'','prop')\n     +kpi(c.prev.length,'Preventivi da fare in chiusura',eur(c.prevV),'','prev')\n     +kpi(zero.length,'Da valorizzare','Proposta o Fare preventivo senza revenue',zero.length?'warn':'','zero')\n     +kpi(c.undated.length,'Senza data di chiusura',eur(c.undV),c.undated.length?'warn':'','undated')\n     +kpi(c.late.length,'Chiusura già scaduta','da riprogrammare',c.late.length?'warn':'','late')\n     +kpi(noPlanList().length,'Senza previsione fatture',eur(noPlanList().reduce((s,l)=>s+l.rev,0)),noPlanList().length?'warn':'','noplan')\n   +'</div>'\n   +block('Fatturato previsto per account',null,'Account Digiduu del cliente. Clicca una riga per il dettaglio.',pipeByAccount())\n   +noPlanBlock()\n   +block('Proposte con chiusura a '+monthName(st.ref),c.prop.length,null,table(sortRev(c.prop),{empty:'Nessuna proposta ha chiusura prevista nel mese. Assegnare la data alle proposte qui sotto per costruire il piano.'}))\n   +block('Fare preventivo con chiusura a '+monthName(st.ref),c.prev.length,null,table(sortRev(c.prev),{empty:'Nessun preventivo da fare con chiusura nel mese.'}))\n   +block('Proposte senza data, già valorizzate',propUnd.length,'Candidate a entrare nel mese: confermare la data di chiusura.',table(propUnd,{empty:'Tutte le proposte valorizzate hanno una data.'}))\n   +block('Fare preventivo senza data, già valorizzate',prevUnd.length,'Preventivi da chiudere per alimentare il mese.',table(prevUnd,{empty:'Nessuna.'}))\n   +block('Da valorizzare',zero.length,'Opportunità in Proposta o Fare preventivo con revenue a zero: senza valore non pesano sul budget.',table(sortRev(zero)))\n   +block('Situazione per addetto',null,'Opportunità in Proposta e Fare preventivo oggi.',byUserTable(u=>{\n      const p=c.pipe.filter(l=>l.user===u);const pr=p.filter(l=>l.stage==='Proposta'),fp=p.filter(l=>l.stage==='Fare preventivo');\n      return [pr.length||'–',pr.length?eur(c.sum(pr)):'–',fp.length||'–',fp.length?eur(c.sum(fp)):'–',p.filter(l=>!l.rev).length||'–',p.filter(l=>!l.deadline).length||'–'];\n   },['Proposte','Valore','Fare prev.','Valore','Da valorizzare','Senza data']));\n}\n\nfunction vMid(){\n  const c=monthCalc();\n  const ev=events(c.ms,st.ref);\n  const g=t=>ev.filter(e=>e.type===t);\n  const uniq=a=>[...new Set(a)];\n  const stageEv=g('stage'), revEv=g('rev');\n  const toProp=stageEv.filter(e=>e.to==='Proposta'), toFP=stageEv.filter(e=>e.to==='Fare preventivo');\n  const lostV=c.lost.reduce((s,l)=>s+l.rev,0);\n  setLists({won:['Vinte nel mese',c.won,true],lost:['Perse nel mese',c.lost,true],new:['Nuove nel mese',g('new').map(e=>e.lead)],stage:['Cambi di fase nel mese',uniq(stageEv.map(e=>e.lead))],rev:['Valorizzate nel mese',uniq(revEv.map(e=>e.lead))],prop:['Proposta con chiusura nel mese',c.prop],prev:['Fare preventivo con chiusura nel mese',c.prev],undated:['Proposta e Fare preventivo senza data',c.undated],toProp:['Passate in Proposta',uniq(toProp.map(e=>e.lead))]});\n  return '<p class=\"lede\">Aggiornamento di metà '+monthName(st.ref)+': movimenti dal '+fd(c.ms)+' al '+fd(st.ref)+'.</p>'\n   +pipeGauge('Fatturato previsto di '+monthName(st.ref)+' al '+fd(st.ref))\n   +'<div class=\"kpis\">'\n     +kpi(eur(c.wonV),'Vinto CRM finora',c.won.length+' opportunità (ordinato)','good','won')\n     +kpi(eur(lostV),'Perso',c.lost.length+' opportunità','bad','lost')\n     +kpi(g('new').length,'Nuove opportunità','','','new')\n     +kpi(toProp.length,'Passate in Proposta',toFP.length+' in Fare preventivo','','toProp')\n     +kpi(uniq(revEv.map(e=>e.lead.id)).length,'Valorizzazioni',eur(revEv.reduce((s,e)=>s+e.amt,0))+' di variazione','','rev')\n   +'</div>'\n   +'<div class=\"grid2\"><div>'+block('Chiuse vinte',c.won.length,null,table([...c.won].sort((a,b)=>b.rev-a.rev),{closed:true,empty:'Nessuna vinta finora nel mese.'}))+'</div>'\n   +'<div>'+block('Chiuse perse',c.lost.length,null,table([...c.lost].sort((a,b)=>b.rev-a.rev),{closed:true,empty:'Nessuna persa nel mese.'}))+'</div></div>'\n   +'<div class=\"grid2\"><div>'+block('Cambi di fase e valorizzazioni',stageEv.length+revEv.length,null,feed([...stageEv,...revEv,...g('user')].sort((x,y)=>y.date.localeCompare(x.date))))+'</div>'\n   +'<div>'+block('Nuove opportunità',g('new').length,null,feed(g('new')))+'</div></div>'\n   +block('Fatturato previsto per account',null,null,pipeByAccount())\n   +noPlanBlock()\n   +block('Movimenti per addetto',null,null,byUserTable(u=>{\n      const e=ev.filter(x=>x.lead.user===u);const w=c.won.filter(l=>l.user===u);\n      return [e.filter(x=>x.type==='new').length||'–',e.filter(x=>x.type==='stage').length||'–',e.filter(x=>x.type==='rev').length||'–',w.length?eur(c.sum(w)):'–',c.lost.filter(l=>l.user===u).length||'–'];\n   },['Nuove','Cambi fase','Valorizz.','Vinto','Perse']));\n}\n\nfunction vEnd(){\n  const c=monthCalc();\n  const pm=pipeMonth(st.ref.slice(0,7));\n  const openIds=new Set(c.pipe.map(l=>l.id));\n  const acts=DATA.activities.filter(x=>openIds.has(x.lead));\n  const due=acts.filter(x=>x.date>=TODAY()&&x.date<=c.me).sort((a,b)=>a.date.localeCompare(b.date));\n  const over=acts.filter(x=>x.date<TODAY()).sort((a,b)=>b.date.localeCompare(a.date));\n  const noAct=c.pipe.filter(l=>!(actsBy[l.id]||[]).length);\n  const stale=c.pipe.filter(l=>l.stage==='Proposta'&&daysBetween(l.stageUpd,st.ref)>45).sort((a,b)=>a.stageUpd.localeCompare(b.stageUpd));\n  const leadsOf=a=>[...new Set(a.map(x=>byId.get(x.lead)))];\n  setLists({won:['Vinte nel mese',c.won,true],prop:['Proposta con chiusura nel mese',c.prop],prev:['Fare preventivo con chiusura nel mese',c.prev],undated:['Proposta e Fare preventivo senza data',c.undated],due:['Attività entro fine mese',leadsOf(due)],over:['Attività scadute',leadsOf(over)],noAct:['Senza attività pianificata',noAct],stale:['Proposte ferme',stale]});\n  const actList=list=>!list.length?'<div class=\"empty\">Nessuna.</div>':'<ul class=\"feed\">'+list.map(x=>{const l=byId.get(x.lead);return '<li tabindex=\"0\" data-id=\"'+l.id+'\"><span class=\"when\">'+fd(x.date)+'</span><span class=\"what\"><b>'+esc(l.name)+'</b><div class=\"sub\">'+esc(x.type)+(x.summary?': '+esc(x.summary):'')+' · '+esc(x.user)+'</div></span><span class=\"amt\">'+(l.rev?eur(l.rev):'')+'</span></li>'}).join('')+'</ul>';\n  return '<p class=\"lede\">Chiusura di '+monthName(st.ref)+': previsione di fatturato dalla pipeline commerciale e ultime azioni sulle opportunità CRM in Proposta e Fare preventivo.</p>'\n   +pipeGauge('Previsione fatturato a chiusura di '+monthName(st.ref))\n   +undatedCallout(c)\n   +'<div class=\"kpis\">'\n     +kpi(eur(pm.v('Fatturato')+pm.v('Contrattualizzato')),'Fatturato + contrattualizzato','fatture confermate e in bozza','good','__p:Fatturato')\n     +kpi(eur(pm.v('Consuntivi')+pm.v('Offerta probabile')),'Probabile','consuntivi + offerte probabili','','__p:Offerta probabile')\n     +kpi(eur(pm.v('Offerta possibile')),'Possibile','offerte con fattibilità possibile','','__p:Offerta possibile')\n     +kpi(eur(Math.max(0,BUDGET-(pm.forecast||0))),'Gap al budget','da coprire con nuove chiusure',(pm.forecast||0)<BUDGET?'bad':'good','__p:__all')\n     +kpi(due.length,'Azioni entro il '+fd(c.me),'su Proposta e Fare preventivo','','due')\n     +kpi(over.length,'Attività scadute','da chiudere o ripianificare',over.length?'warn':'','over')\n     +kpi(noAct.length,'Senza prossimo passo','nessuna attività pianificata',noAct.length?'warn':'','noAct')\n   +'</div>'\n   +block('Fatturato previsto per account',null,null,pipeByAccount())\n   +noPlanBlock()\n   +block('Andamento '+st.ref.slice(0,4),null,'Fatturato previsto per mese dalla pipeline commerciale (passato: consuntivo fatture; futuro: bozze + piano di fatturazione).',yearChart())\n   +block('Da chiudere entro fine mese',c.prop.length+c.prev.length,'Proposta e Fare preventivo con chiusura prevista nel mese.',table([...c.prop,...c.prev].sort((a,b)=>b.rev-a.rev),{empty:'Nessuna opportunità ha chiusura prevista nel mese: la previsione coincide con il vinto.'}))\n   +'<div class=\"grid2\"><div>'+block('Ultime azioni pianificate',due.length,'Attività da qui a fine mese.',actList(due))+'</div>'\n   +'<div>'+block('Attività scadute',over.length,'Su opportunità in Proposta e Fare preventivo.',actList(over))+'</div></div>'\n   +block('Proposte ferme da oltre 45 giorni',stale.length,'Sollecitare, riprogrammare o chiudere.',table(stale,{empty:'Nessuna proposta ferma.'}))\n   +block('Senza prossimo passo',noAct.length,'Nessuna attività aperta in Odoo.',table(noAct,{empty:'Tutte hanno un’attività.'}))\n   +block('Vinte nel mese',c.won.length,null,table([...c.won].sort((a,b)=>b.rev-a.rev),{closed:true,empty:'Nessuna vinta nel mese.'}));\n}\n\nfunction vYear(){\n  const y=st.ref.slice(0,4), cur=DATA.extracted.slice(0,7);\n  const rows=[...Array(12)].map((_,i)=>{const m=y+'-'+String(i+1).padStart(2,'0');const p=pipeMonth(m);\n    const vals=p.detail?PSTATES.map(([s])=>p.v(s)):(p.forecast==null?PSTATES.map(()=>null):[p.forecast,0,0,0,0]);\n    return {m,i,vals,tot:p.forecast,detail:p.detail};});\n  let cum=0,cumB=0;\n  const sums=PSTATES.map((_,k)=>rows.reduce((a,r)=>a+(r.vals[k]||0),0));\n  const grand=rows.reduce((a,r)=>a+(r.tot||0),0);\n  const done=rows.filter(r=>r.m<cur), ytd=done.reduce((a,r)=>a+(r.tot||0),0);\n  const prob=grand-sums[PSTATES.findIndex(s=>s[0]==='Offerta possibile')];\n  const cell=v=>v==null?'<td class=\"num\" style=\"color:var(--ink3)\">n.d.</td>':'<td class=\"num\">'+(v?eur(v):'–')+'</td>';\n  const body=rows.map(r=>{cum+=r.tot||0;cumB+=BUDGET;const diff=(r.tot||0)-BUDGET;\n    const tag=r.m<cur?'consuntivo':r.m===cur?'in corso':'previsione';\n    return '<tr'+(r.m===cur?' style=\"background:#F4F0FF\"':'')+'><td style=\"font-weight:600\">'+MESI[r.i].replace(/^./,c=>c.toUpperCase())+' <span class=\"chip\" style=\"margin-left:4px\">'+tag+'</span></td>'\n      +r.vals.map(cell).join('')\n      +'<td class=\"num\" style=\"font-weight:700\">'+(r.tot==null?'n.d.':eur(r.tot))+'</td>'\n      +'<td class=\"num\" style=\"color:'+(diff>=0?'var(--green)':'var(--red)')+'\">'+(r.tot==null?'':(diff>=0?'+':'')+eur(diff))+'</td>'\n      +'<td class=\"num\">'+eur(cum)+'</td><td class=\"num\" style=\"color:'+(cum-cumB>=0?'var(--green)':'var(--red)')+'\">'+(cum-cumB>=0?'+':'')+eur(cum-cumB)+'</td></tr>';}).join('');\n  const foot='<tr style=\"border-top:2px solid var(--ink)\"><td style=\"font-weight:700\">Totale '+y+'</td>'+sums.map(v=>'<td class=\"num\" style=\"font-weight:700\">'+eur(v)+'</td>').join('')\n    +'<td class=\"num\" style=\"font-weight:800\">'+eur(grand)+'</td><td class=\"num\" style=\"font-weight:700;color:'+(grand-BUDGET*12>=0?'var(--green)':'var(--red)')+'\">'+(grand-BUDGET*12>=0?'+':'')+eur(grand-BUDGET*12)+'</td><td></td><td></td></tr>';\n  return '<p class=\"lede\">Riepilogo '+y+': consuntivo fatturato dei mesi chiusi e previsione dei mesi aperti dalla pipeline commerciale, contro un budget di '+eur(BUDGET)+' al mese ('+eur(BUDGET*12)+' l’anno).</p>'\n   +'<div class=\"kpis\">'\n     +kpi(eur(ytd),done.length?'Fatturato gen–'+MESI[done.length-1].slice(0,3):'Fatturato a oggi',done.length?done.length+' mesi chiusi':'anno non ancora iniziato','good','')\n     +kpi(eur(grand),'Previsione anno','consuntivo + previsione mesi aperti','','')\n     +kpi(eur(prob),'Previsione anno senza possibili','esclude le offerte possibili','','')\n     +kpi((grand-BUDGET*12>=0?'+':'')+eur(grand-BUDGET*12),'Scostamento dal budget annuo',eur(BUDGET*12),grand>=BUDGET*12?'good':'bad','')\n     +kpi(Math.round(grand/(BUDGET*12)*100)+'%','Copertura budget annuo','','','')\n   +'</div>'\n   +block('Andamento mensile',null,null,yearChart())\n   +block('Tabella riepilogativa e previsionale',null,(y==='2026'?'Gennaio–agosto: totale fatture confermate (dettaglio per voce e account non disponibile). Da settembre: fatture confermate e in bozza più piano di fatturazione.':'Fatture già emesse in bozza (canoni e tranche contrattualizzate) più piano di fatturazione in Consuntivi e Proposta già inserito per il '+y+'.')+(st.user?' Con il filtro addetto i mesi senza dettaglio non sono calcolabili.':''),\n     '<div class=\"tw\"><table><thead><tr><th>Mese</th>'+PSTATES.map(([s])=>'<th class=\"num\">'+s+'</th>').join('')+'<th class=\"num\">Totale</th><th class=\"num\">vs budget</th><th class=\"num\">Progressivo</th><th class=\"num\">Progr. vs budget</th></tr></thead><tbody>'+body+foot+'</tbody></table></div>');\n}\n\n/* dettaglio */\nconst dlg=document.getElementById('dlg'), dlgIn=document.getElementById('dlgIn');\nfunction openLead(id){\n  const l=byId.get(+id); if(!l) return;\n  const acts=actsBy[l.id]||[], tr=(trackBy[l.id]||[]).slice().sort((a,b)=>b.date.localeCompare(a.date));\n  const kindL={S:'Fase',R:'Revenue',U:'Addetto'};\n  dlgIn.innerHTML='<div class=\"dlg-head\"><button class=\"close\" aria-label=\"Chiudi\">×</button><h2>'+esc(l.name)+'</h2><div class=\"p\">'+esc(l.partner)+'</div><div style=\"margin-top:8px\">'+stageChip(l.stage)+(l.tags||[]).map(t=>'<span class=\"chip\">'+esc(t)+'</span>').join('')+'</div></div>'\n   +'<div class=\"dlg-body\"><div class=\"facts\">'\n   +'<div>Revenue<b>'+(l.rev?eur(l.rev):'<span class=\"zero\">da valorizzare</span>')+'</b></div>'\n   +'<div>Addetto vendite<b>'+esc(l.user)+'</b></div>'\n   +'<div>Priorità<b>'+stars(l.prio)+'</b></div>'\n   +(l.status==='open'\n      ?(STAGES_CLOSE.includes(l.stage)?'<div>Preventivo Odoo<b>'+(ordersTxt(l)||'<span class=\"zero\">nessuno</span>')+'</b></div><div>Previsione fatture<b>'+(hasPlan(l)?'Sì':'<span class=\"zero\">non pianificata</span>')+'</b></div>':'')+'<div>Chiusura prevista<b>'+(l.deadline?fd(l.deadline):'<span class=\"zero\">da inserire</span>')+'</b></div><div>Creata<b>'+fd(l.created)+'</b></div><div>Ultimo cambio fase<b>'+fd(l.stageUpd)+' ('+daysBetween(l.stageUpd,st.ref)+' gg fa)</b></div><div>Ultima modifica<b>'+fd(l.updated)+'</b></div>'\n      :'<div>'+(l.status==='won'?'Vinta il':'Persa il')+'<b>'+fd(l.closed)+'</b></div>'+(l.lostReason?'<div>Motivo<b>'+esc(l.lostReason)+'</b></div>':''))\n   +'</div>'\n   +'<h4>Attività assegnate</h4>'+(acts.length?'<ul class=\"list-plain\">'+acts.map(a=>'<li><span style=\"font-weight:600'+(a.date<TODAY()?';color:var(--red)':'')+'\">'+fd(a.date)+'</span> · '+esc(a.type)+(a.summary?': '+esc(a.summary):'')+'<div class=\"m\">'+esc(a.user)+(a.date<TODAY()?' · scaduta':'')+'</div></li>').join('')+'</ul>':'<div class=\"empty\">Nessuna attività aperta.</div>')\n   +(tr.length?'<h4>Storico modifiche</h4><ul class=\"list-plain\">'+tr.map(t=>'<li><span style=\"font-weight:600\">'+fd(t.date)+'</span> · '+kindL[t.kind]+': '+(t.kind==='R'?eur(t.old)+' → '+eur(t.new):esc(t.old)+' → '+esc(t.new))+'<div class=\"m\">'+esc(t.author)+'</div></li>').join('')+'</ul>':'')\n   +'<a class=\"btn\" href=\"'+DATA.odooUrl+l.id+'\" target=\"_blank\" rel=\"noopener\">Apri in Odoo</a></div>';\n  dlg.showModal(); dlg.scrollTop=0;\n}\nfunction openList(key){\n  const L=LISTS[key]; if(!L) return;\n  const [title,list,closed,ord]=L;\n  const tot=list.reduce((s,l)=>s+(l?l.rev:0),0);\n  dlgIn.innerHTML='<div class=\"dlg-head\"><button class=\"close\" aria-label=\"Chiudi\">×</button><h2>'+esc(title)+'</h2><div class=\"p\">'+list.length+' opportunità · '+eur(tot)+'</div></div><div class=\"dlg-body\">'+table(list.filter(Boolean),{closed,orders:ord,empty:'Nessuna opportunità.'})+'</div>';\n  dlg.showModal();\n}\nfunction openUser(u){\n  const list=openLeads().filter(l=>l.user===u && STAGES_CLOSE.includes(l.stage));\n  LISTS.__u=['Proposta e Fare preventivo di '+u,list]; openList('__u');\n}\ndlg.addEventListener('click',e=>{\n  if(e.target===dlg||e.target.closest('.close')) return dlg.close();\n  const r=e.target.closest('[data-id]'); if(r) openLead(r.dataset.id);\n});\n\n/* render */\nfunction render(){\n  document.querySelectorAll('.tab').forEach(t=>t.setAttribute('aria-selected',t.dataset.v===st.view));\n  const v=document.getElementById('view');\n  v.innerHTML={week:vWeek,start:vStart,mid:vMid,end:vEnd,year:vYear}[st.view]();\n  const t=document.getElementById('undTgl'); if(t) t.onchange=()=>{st.undated=t.checked;render()};\n}\ndocument.querySelector('.tabs').onclick=e=>{const b=e.target.closest('.tab'); if(b){st.view=b.dataset.v;render()}};\ndocument.getElementById('view').addEventListener('click',e=>{\n  const pp=e.target.closest('[data-p]'); if(pp) return openPipe(pp.dataset.p);\n  const k=e.target.closest('[data-k]'); if(k){e.preventDefault(); if(k.dataset.k.startsWith('__p:')) return openPipe(k.dataset.k.slice(4)); return openList(k.dataset.k)}\n  const ac=e.target.closest('[data-acc]'); if(ac){ PIPE_LISTS.__acc=pipeMonth(st.ref.slice(0,7)).rows.filter(r=>r.account===ac.dataset.acc&&r.state!=='Target'); dlgIn.innerHTML='<div class=\"dlg-head\"><button class=\"close\" aria-label=\"Chiudi\">×</button><h2>'+esc(ac.dataset.acc)+'</h2><div class=\"p\">Fatturato previsto di '+monthName(st.ref)+' · '+eur(PIPE_LISTS.__acc.reduce((a,r)=>a+r.value,0))+'</div></div><div class=\"dlg-body\">'+pipeTable(PIPE_LISTS.__acc)+'</div>'; return dlg.showModal(); }\n  const r=e.target.closest('[data-id]'); if(r) return openLead(r.dataset.id);\n  const u=e.target.closest('[data-user]'); if(u) return openUser(u.dataset.user);\n});\ndocument.getElementById('view').addEventListener('keydown',e=>{if(e.key==='Enter'){const r=e.target.closest('[data-id]');if(r)openLead(r.dataset.id)}});\nconst rd=document.getElementById('refDate'), ms=document.getElementById('monthSel');\nconst MONTHS=['2026-09','2026-10','2026-11','2026-12','2027-01','2027-02','2027-03','2027-04','2027-05','2027-06','2027-07','2027-08','2027-09','2027-10','2027-11','2027-12'];\nMONTHS.forEach(m=>ms.insertAdjacentHTML('beforeend','<option value=\"'+m+'\">'+MESI[+m.slice(5)-1].replace(/^./,c=>c.toUpperCase())+' '+m.slice(0,4)+'</option>'));\nfunction syncCtl(){ rd.value=st.ref; ms.value=st.ref.slice(0,7); }\nms.onchange=()=>{\n  const m=ms.value, cur=DATA.extracted.slice(0,7);\n  // mese corrente: data di estrazione; mesi passati: ultimo giorno; mesi futuri: primo giorno\n  st.ref = m===cur ? DATA.extracted : (m<cur ? monthEnd(m+'-01') : m+'-01');\n  if(m>cur && st.view!=='start' && st.view!=='end') st.view='start';\n  syncCtl(); render();\n};\nrd.onchange=()=>{if(rd.value){st.ref=rd.value;syncCtl();render()}};\nconst us=document.getElementById('userSel');\n[...new Set(DATA.leads.map(l=>l.user))].sort().forEach(u=>us.insertAdjacentHTML('beforeend','<option>'+esc(u)+'</option>'));\nus.onchange=()=>{st.user=us.value;render()};\ndocument.getElementById('srcNote').textContent='CRM Odoo, dati estratti il '+d(DATA.extracted).toLocaleDateString('it-IT')+' · budget mensile '+eur(BUDGET);\n// vista iniziale in base al giorno del mese\n(()=>{const g=d(st.ref).getDate(); st.view=g<=7?'start':g<=20?'mid':'end'})();\nsyncCtl();\nrender();\n</script>\n</body>\n</html>\n";
